add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_variation_price_replaces_range' );

function perfectpixel_variation_price_replaces_range() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	?>
	<style>.single-product .woocommerce-variation-price{display:none}</style>
	<script>
	jQuery( function ( $ ) {
		var top      = $( '.summary p.price, .summary .wp-block-woocommerce-product-price' ).first();
		var original = top.html();
		$( 'form.variations_form' ).on( 'found_variation', function ( e, v ) {
			if ( v.price_html ) {
				top.html( $( '<div>' ).html( v.price_html ).find( '.price' ).html() || v.price_html );
			}
		} ).on( 'reset_data', function () {
			top.html( original );
		} );
	} );
	</script>
	<?php
}
